import { MatButtonToggleModule } from '@angular/material/button-toggle';
import { MatDatepickerModule } from '@angular/material/datepicker';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { MatNativeDateModule, provideNativeDateAdapter } from '@angular/material/core';
import { MatRadioModule } from '@angular/material/radio';
import { MatSelectModule } from '@angular/material/select';
import { TranslocoModule } from '@jsverse/transloco';
import { RRule, Frequency, Weekday } from 'rrule';
import { Subscription } from 'rxjs';
import { BaseEditable } from '../base-editable';
import { EditableHiddenMarkComponent } from '../editable-hidden-mark/editable-hidden-mark.component';

export type RRuleFreq = 'DAILY' | 'WEEKLY' | 'MONTHLY' | 'YEARLY';

type EndMode = 'never' | 'until' | 'count';

const FREQ_MAP: Record<RRuleFreq, Frequency> = {
  DAILY: Frequency.DAILY,
  WEEKLY: Frequency.WEEKLY,
  MONTHLY: Frequency.MONTHLY,
  YEARLY: Frequency.YEARLY,
};

const FREQ_LABELS: Record<RRuleFreq, string> = {
  DAILY: 'Diario',
  WEEKLY: 'Semanal',
  MONTHLY: 'Mensual',
  YEARLY: 'Anual',
};

const WEEKDAY_OPTS = [
  { label: 'L', day: RRule.MO },
  { label: 'M', day: RRule.TU },
  { label: 'X', day: RRule.WE },
  { label: 'J', day: RRule.TH },
  { label: 'V', day: RRule.FR },
  { label: 'S', day: RRule.SA },
  { label: 'D', day: RRule.SU },
];

interface RRuleState {
  freq: RRuleFreq;
  interval: number;
  byWeekDay: Weekday[];
  byMonthDay: number;
  byMonth: number;
  endMode: EndMode;
  until: Date | null;
  count: number;
}

@Component({
  selector: 'editable-rrule',
  standalone: true,
  imports: [
    CommonModule,
    FormsModule,
    ReactiveFormsModule,
    MatFormFieldModule,
    MatInputModule,
    MatSelectModule,
    MatDatepickerModule,
    MatNativeDateModule,
    MatRadioModule,
    MatButtonToggleModule,
    TranslocoModule,
    EditableHiddenMarkComponent,
  ],
  providers: [provideNativeDateAdapter(), BaseEditable.getValidableAccessorProvider(EditableRruleComponent)],
  templateUrl: './editable-rrule.component.html',
  styleUrls: ['./editable-rrule.component.scss'],
})
export class EditableRruleComponent extends BaseEditable<string> implements OnInit, OnDestroy {
  startDate = input<Date>(new Date());
  minDate = input<Date | null>(null);
  maxDate = input<Date | null>(null);
  maxOccurrences = input<number>(52);
  allowedFrequencies = input<RRuleFreq[]>(['DAILY', 'WEEKLY', 'MONTHLY', 'YEARLY']);

  readonly weekdays = WEEKDAY_OPTS;
  readonly freqLabels = FREQ_LABELS;
  readonly days = Array.from({ length: 31 }, (_, i) => i + 1);
  readonly months = [
    'Enero',
    'Febrero',
    'Marzo',
    'Abril',
    'Mayo',
    'Junio',
    'Julio',
    'Agosto',
    'Septiembre',
    'Octubre',
    'Noviembre',
    'Diciembre',
  ];

  state = signal<RRuleState>({
    freq: 'WEEKLY',
    interval: 1,
    byWeekDay: [],
    byMonthDay: 1,
    byMonth: 1,
    endMode: 'never',
    until: null,
    count: 10,
  });

  intervalControl = new FormControl<number>(1, { nonNullable: true });

  rule = computed(() => this.buildRule(this.state()));

  humanText = computed(() => {
    try {
      return this.rule().toText();
    } catch {
      return '';
    }
  });

  nextOccurrences = computed(() => {
    try {
      return this.rule()
        .between(this.startDate(), new Date(this.startDate().getTime() + 365 * 10 * 86_400_000), true)
        .slice(0, 5);
    } catch {
      return [];
    }
  });

  private subs = new Subscription();

  override ngOnInit(): void {
    super.ngOnInit();

    this.subs.add(
      this.control.valueChanges.subscribe((external: string | null) => {
        if (external) this.parseExternal(external);
      }),
    );

    this.subs.add(
      this.intervalControl.valueChanges.subscribe((v) => {
        this.patchState({ interval: Math.max(1, v || 1) });
      }),
    );
  }

  override ngOnDestroy(): void {
    this.subs.unsubscribe();
    super.ngOnDestroy();
  }

  patchState(partial: Partial<RRuleState>): void {
    this.state.update((s) => ({ ...s, ...partial }));
    this.emit();
  }

  toggleWeekday(wd: Weekday): void {
    const current = this.state().byWeekDay;
    const exists = current.some((d) => d.weekday === wd.weekday);
    const next = exists ? current.filter((d) => d.weekday !== wd.weekday) : [...current, wd];
    this.patchState({ byWeekDay: next });
  }

  isWeekdaySelected(wd: Weekday): boolean {
    return this.state().byWeekDay.some((d) => d.weekday === wd.weekday);
  }

  override validate(_: any) {
    const s = this.state();
    const errs: Record<string, boolean> = {};

    if (s.freq === 'WEEKLY' && s.byWeekDay.length === 0) {
      errs['rruleNoDaysSelected'] = true;
    }
    if (s.endMode === 'until' && s.until && s.until < this.startDate()) {
      errs['rruleUntilBeforeStart'] = true;
    }
    if (s.endMode === 'count' && s.count <= 0) {
      errs['rruleCountInvalid'] = true;
    }

    try {
      this.rule();
    } catch {
      errs['rruleInvalidExpression'] = true;
    }

    return Object.keys(errs).length ? errs : null;
  }

  private emit(): void {
    try {
      this.updateValue(this.rule().toString());
    } catch {
      this.updateValue(null);
    }
  }

  private buildRule(s: RRuleState): RRule {
    const opts: ConstructorParameters<typeof RRule>[0] = {
      freq: FREQ_MAP[s.freq],
      interval: s.interval,
      dtstart: this.startDate(),
    };

    if (s.freq === 'WEEKLY' && s.byWeekDay.length) {
      opts.byweekday = s.byWeekDay;
    }
    if (s.freq === 'MONTHLY') {
      opts.bymonthday = s.byMonthDay;
    }
    if (s.freq === 'YEARLY') {
      opts.bymonth = s.byMonth;
      opts.bymonthday = s.byMonthDay;
    }
    if (s.endMode === 'until' && s.until) {
      opts.until = s.until;
    } else if (s.endMode === 'count') {
      opts.count = s.count;
    }

    return new RRule(opts);
  }

  private parseExternal(expr: string): void {
    try {
      const rule = RRule.fromString(expr);
      const opts = rule.origOptions;
      const freqEntry = Object.entries(FREQ_MAP).find(([, v]) => v === opts.freq);
      if (!freqEntry) return;

      this.patchState({
        freq: freqEntry[0] as RRuleFreq,
        interval: (opts.interval as number) || 1,
        byWeekDay: (opts.byweekday as Weekday[]) || [],
        byMonthDay: (Array.isArray(opts.bymonthday) ? opts.bymonthday[0] : opts.bymonthday) || 1,
        byMonth: (Array.isArray(opts.bymonth) ? opts.bymonth[0] : opts.bymonth) || 1,
        endMode: opts.until ? 'until' : opts.count ? 'count' : 'never',
        until: (opts.until as Date) || null,
        count: (opts.count as number) || 10,
      });
    } catch {}
  }
}
